const mongoose = require("mongoose");

// ======================================================
// FACE ENROLLMENT SCHEMA
// ======================================================

const faceEnrollmentSchema = new mongoose.Schema(
  {
    status: {
      type: String,
      enum: [
        "Not Enrolled",
        "Pending",
        "Enrolled",
        "Disabled",
      ],
      default: "Not Enrolled",
    },

    // Name of the compatible face-recognition provider.
    provider: {
      type: String,
      trim: true,
      default: "",
    },

    // Numeric face descriptor generated by a compatible
    // face-recognition model.
    //
    // The original image is not stored in this field.
    // The descriptor is excluded from normal queries.
    faceDescriptor: {
      type: [Number],
      default: undefined,
      select: false,
    },

    enrolledAt: {
      type: Date,
      default: null,
    },

    lastVerifiedAt: {
      type: Date,
      default: null,
    },

    // Increment whenever the employee re-enrolls.
    enrollmentVersion: {
      type: Number,
      min: 0,
      default: 0,
    },
  },
  {
    _id: false,
  }
);

// ======================================================
// BIOMETRIC CONSENT SCHEMA
// ======================================================

const biometricConsentSchema = new mongoose.Schema(
  {
    given: {
      type: Boolean,
      default: false,
    },

    consentedAt: {
      type: Date,
      default: null,
    },

    consentVersion: {
      type: String,
      trim: true,
      default: "",
    },
  },
  {
    _id: false,
  }
);

// ======================================================
// EMPLOYEE SCHEMA
// ======================================================

const employeeSchema = new mongoose.Schema(
  {
    // Employee identification.
    employeeId: {
      type: String,
      trim: true,
      default: undefined,
    },

    // Link employee profile to login account.
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      unique: true,
      sparse: true,
      default: undefined,
    },

    // Basic employee information.
    name: {
      type: String,
      required: true,
      trim: true,
    },

    email: {
      type: String,
      trim: true,
      lowercase: true,
      default: "",
    },

    phone: {
      type: String,
      trim: true,
      default: "",
    },

    department: {
      type: String,
      trim: true,
      default: "",
    },

    designation: {
      type: String,
      trim: true,
      default: "",
    },

    salary: {
      type: Number,
      min: 0,
      default: 0,
    },

    joiningDate: {
      type: String,
      trim: true,
      default: "",
    },

    employmentType: {
      type: String,
      enum: [
        "Full-time",
        "Part-time",
        "Intern",
        "Contract",
      ],
      default: "Full-time",
    },

    status: {
      type: String,
      trim: true,
      enum: [
        "Active",
        "On Leave",
        "Inactive",
      ],
      default: "Active",
    },

    // ==================================================
    // FACE ENROLLMENT
    // ==================================================

    faceEnrollment: {
      type: faceEnrollmentSchema,

      default: () => ({
        status: "Not Enrolled",
        enrollmentVersion: 0,
      }),
    },

    // ==================================================
    // BIOMETRIC CONSENT
    // ==================================================

    biometricConsent: {
      type: biometricConsentSchema,

      default: () => ({
        given: false,
        consentedAt: null,
        consentVersion: "",
      }),
    },
  },
  {
    timestamps: true,

    // Preserve additional fields already used by the ERP.
    strict: false,
  }
);

// ======================================================
// EMPLOYEE ID INDEX
// ======================================================

employeeSchema.index(
  {
    employeeId: 1,
  },
  {
    unique: true,

    partialFilterExpression: {
      employeeId: {
        $type: "string",
        $gt: "",
      },
    },
  }
);

// ======================================================
// EXPORT MODEL
// ======================================================

module.exports =
  mongoose.models.Employee ||
  mongoose.model("Employee", employeeSchema);